1	/*!
2	 * \file tl/cuda/op/gemm.cc
3	 * \brief CUDA implementation for tl.gemm instruction selection.
4	 */
5	
6	#include "op/gemm.h"
7	#include "support/check.h"
8	#include <tvm/runtime/logging.h>
9	
10	#include "cuda/target_utils.h"
11	#include "op/builtin.h"
12	#include "op/tcgen5_meta.h"
13	#include "op/utils.h"
14	
15	#include <tvm/tirx/transform.h>
16	
17	#include <algorithm>
18	#include <cmath>
19	#include <cstdint>
20	#include <limits>
21	#include <utility>
22	
23	namespace tvm {
24	namespace tl {
25	
26	using namespace tirx;
27	using namespace ffi;
28	
29	namespace cuda {
30	
31	namespace {
32	
33	constexpr const char *kCudaMMA = "cuda.mma";
34	constexpr const char *kCudaWGMMA = "cuda.wgmma";
35	constexpr const char *kCudaTCGEN05 = "cuda.tcgen05";
36	
37	bool CheckWgmma(const GemmNode &op) {
38	  if (op.b_.scope() != "shared.dyn" && op.b_.scope() != "shared") {
39	    return false;
40	  }
41	
42	  if (op.c_->dtype == DataType::Float(16)) {
43	    if (op.a_->dtype == DataType::Float(16) &&
44	        op.b_->dtype == DataType::Float(16))
45	      return op.k_ % 16 == 0;
46	    if (op.a_->dtype.is_float8() && op.b_->dtype.is_float8())
47	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
48	    return false;
49	  }
50	  if (op.c_->dtype == DataType::Float(32)) {
51	    if (op.a_->dtype == DataType::Float(16) &&
52	        op.b_->dtype == DataType::Float(16))
53	      return op.k_ % 16 == 0;
54	    if (op.a_->dtype == DataType::BFloat(16) &&
55	        op.b_->dtype == DataType::BFloat(16))
56	      return op.k_ % 16 == 0;
57	    if (op.a_->dtype.is_tfloat32() && op.b_->dtype.is_tfloat32())
58	      return (!op.transA_) && op.transB_ && op.k_ % 8 == 0;
59	    if (op.a_->dtype.is_float8() && op.b_->dtype.is_float8())
60	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
61	    return false;
62	  }
63	  if (op.c_->dtype == DataType::Int(32)) {
64	    if (op.a_->dtype == DataType::Int(8) && op.b_->dtype == DataType::Int(8))
65	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
66	    if (op.a_->dtype == DataType::Int(8) && op.b_->dtype == DataType::UInt(8))
67	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
68	    if (op.a_->dtype == DataType::UInt(8) && op.b_->dtype == DataType::Int(8))
69	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
70	    if (op.a_->dtype == DataType::UInt(8) && op.b_->dtype == DataType::UInt(8))
71	      return (!op.transA_) && op.transB_ && op.k_ % 32 == 0;
72	    return false;
73	  }
74	  return false;
75	}
76	
77	bool AllowTcgen5Mma(const GemmNode &op, Target target) {
78	  bool scope_ok = (IsSharedBuffer(op.a_) || op.a_.scope() == "shared.tmem") &&
79	                  IsSharedBuffer(op.b_) && op.c_.scope() == "shared.tmem";
80	  if (!TargetIsSm100(target) || !scope_ok)
81	    return false;
82	  DataType ab_dtype =
83	      (op.a_.scope() == "shared.tmem") ? op.b_->dtype : op.a_->dtype;
84	  return GetTCGEN5MMAMeta(op.m_, op.n_, op.k_, ab_dtype, op.c_->dtype).first;
85	}
86	
87	bool AllowWgmma(const GemmNode &op, int block_size, Target target) {
88	  tvm::transform::PassContext ctxt = tvm::transform::PassContext::Current();
89	
90	  int warp_size = TargetCudaGetWarpSize(target);
91	  int num_warps = block_size / warp_size;
92	  return !ctxt->GetConfig(kDisableWGMMA, Optional<Bool>()).value_or(false) &&
93	         TargetIsHopper(target) && op.m_ >= 64 && num_warps % 4 == 0 &&
94	         CheckWgmma(op);
95	}
96	
97	void FatalWgmmaUnavailable(const GemmNode &op, Target target) {
98	  LOG(FATAL) << "T.wgmma_gemm() requires Hopper WGMMA lowering, but "
99	                "constraints were not satisfied. Got target="
100	             << target << ", A(scope=" << op.a_.scope()
101	             << ", dtype=" << op.a_->dtype << "), B(scope=" << op.b_.scope()
102	             << ", dtype=" << op.b_->dtype << "), C(scope=" << op.c_.scope()
103	             << ", dtype=" << op.c_->dtype << "), M=" << op.m_
104	             << ", N=" << op.n_ << ", K=" << op.k_ << ".";
105	}
106	
107	void FatalTcgen5Unavailable(const GemmNode &op, Target target) {
108	  LOG(FATAL) << "T.tcgen05_gemm() requires Blackwell TCGEN5MMA lowering, "
109	                "but constraints were not satisfied. Got target="
110	             << target << ", A(scope=" << op.a_.scope()
111	             << ", dtype=" << op.a_->dtype << "), B(scope=" << op.b_.scope()
112	             << ", dtype=" << op.b_->dtype << "), C(scope=" << op.c_.scope()
113	             << ", dtype=" << op.c_->dtype << "), M=" << op.m_
114	             << ", N=" << op.n_ << ", K=" << op.k_ << ".";
115	}
116	
117	std::pair<int, int>
118	ComputeDefaultWarpPartition(const GemmWarpPolicyNode &policy, int M, int N,
119	                            int num_warps, int k_n_per_warp) {
120	  int m_warp = 1, n_warp = 1;
121	  constexpr int kMPerWarp = 16;
122	
123	  ICHECK(M % kMPerWarp == 0)
124	      << "M must be divisible by " << kMPerWarp << ", but got " << M;
125	  ICHECK(N % k_n_per_warp == 0)
126	      << "N must be divisible by " << k_n_per_warp << ", but got " << N;
127	
128	  if (policy.IsFullRow()) {
129	    m_warp = num_warps;
130	    n_warp = 1;
131	    if (M % (m_warp * kMPerWarp) != 0) {
132	      int max_m_warps = M / kMPerWarp;
133	      m_warp = max_m_warps;
134	      n_warp = num_warps / m_warp;
135	      if (n_warp == 0)
136	        n_warp = 1;
137	    }
138	  } else if (policy.IsFullCol()) {
139	    m_warp = 1;
140	    n_warp = num_warps;
141	    if (N % (n_warp * k_n_per_warp) != 0) {
142	      int max_n_warps = N / k_n_per_warp;
143	      n_warp = max_n_warps;
144	      m_warp = num_warps / n_warp;
145	      if (m_warp == 0)
146	        m_warp = 1;
147	    }
148	  } else if (policy.IsSquare()) {
149	    int max_m_warps = M / kMPerWarp;
150	    float ideal_ratio = N > 0 ? static_cast<float>(M) / N : 1.0f;
151	
152	    int best_m = 1;
153	    int best_n = 1;
154	    float best_balance = std::numeric_limits<float>::max();
155	    for (int m = 1; m <= max_m_warps && m <= num_warps; m++) {
156	      int n = num_warps / m;
157	
158	      float m_per_warp = static_cast<float>(M) / (m * kMPerWarp);
159	      float n_per_warp = static_cast<float>(N) / (n * k_n_per_warp);
160	      if (m_per_warp < 1 || n_per_warp < 1)
161	        continue;
162	      if (m * n != num_warps)
163	        continue;
164	
165	      float balance = std::abs(m_per_warp / n_per_warp - ideal_ratio);
166	      if (balance < best_balance) {
167	        best_balance = balance;
168	        best_m = m;
169	        best_n = n;
170	      }
171	    }
172	
173	    m_warp = best_m;
174	    n_warp = best_n;
175	  } else {
176	    ICHECK(0) << "Unknown GemmWarpPolicy";
177	  }
178	
179	  ICHECK(m_warp * n_warp == num_warps)
180	      << "m_warp * n_warp must equal num_warps, m_warp: " << m_warp
181	      << ", n_warp: " << n_warp << ", num_warps: " << num_warps;
182	  policy.m_warp = m_warp;
183	  policy.n_warp = n_warp;
184	  return {m_warp, n_warp};
185	}
186	
187	std::pair<int, int> ComputeWgmmaWarpPartition(const GemmWarpPolicyNode &policy,
188	                                              int M, int N, int num_warps) {
189	  ICHECK(num_warps % 4 == 0) << "Warp-Group MMA requires 128*k threads.";
190	
191	  int m_warp = 1, n_warp = 1;
192	  constexpr int kMPerWarp = 16;
193	  constexpr int kNPerWarp = 8;
194	  constexpr int kGroup = 4;
195	
196	  ICHECK(M % kMPerWarp == 0)
197	      << "M must be divisible by " << kMPerWarp << ", but got " << M;
198	  ICHECK(N % kNPerWarp == 0)
199	      << "N must be divisible by " << kNPerWarp << ", but got " << N;
200	
201	  m_warp = kGroup;
202	  n_warp = num_warps / m_warp;
203	
204	  if (policy.IsFullRow()) {
205	    for (int cand = num_warps; cand >= kGroup; cand -= kGroup) {
206	      if (M % (cand * kMPerWarp) == 0) {
207	        m_warp = cand;
208	        n_warp = num_warps / m_warp;
209	        break;
210	      }
211	    }
212	  } else if (policy.IsFullCol()) {
213	    int cand_n = n_warp;
214	    if (N % (cand_n * kNPerWarp) != 0) {
215	      int max_n = N / kNPerWarp;
216	      for (int n = std::min(cand_n, max_n); n >= 1; --n) {
217	        if (num_warps % n == 0 && (num_warps / n) % kGroup == 0) {
218	          n_warp = n;
219	          m_warp = num_warps / n_warp;
220	          break;
221	        }
222	      }
223	    }
224	  } else if (policy.IsSquare()) {
225	    int max_m = M / kMPerWarp;
226	    int max_n = N / kNPerWarp;
227	
228	    float ideal = N > 0 ? static_cast<float>(M) / N : 1.f;
229	    float best_score = std::numeric_limits<float>::max();
230	    int best_m = kGroup, best_n = n_warp;
231	
232	    for (int m = kGroup; m <= num_warps && m <= max_m; m += kGroup) {
233	      if (num_warps % m)
234	        continue;
235	      int n = num_warps / m;
236	      if (n > max_n)
237	        continue;
238	
239	      float m_per_warp = static_cast<float>(M) / (m * kMPerWarp);
240	      float n_per_warp = static_cast<float>(N) / (n * kNPerWarp);
241	      float score = std::abs(m_per_warp / n_per_warp - ideal);
242	
243	      if (score < best_score) {
244	        best_score = score;
245	        best_m = m;
246	        best_n = n;
247	      }
248	    }
249	    m_warp = best_m;
250	    n_warp = best_n;
251	  } else {
252	    ICHECK(0) << "Unknown GemmWarpPolicy";
253	  }
254	
255	  ICHECK(m_warp * n_warp == num_warps)
256	      << "m_warp * n_warp must equal num_warps, m_warp: " << m_warp
257	      << ", n_warp: " << n_warp << ", num_warps: " << num_warps;
258	  policy.m_warp = m_warp;
259	  policy.n_warp = n_warp;
260	  return {m_warp, n_warp};
261	}
262	
263	} // namespace
264	
265	struct Gemm {
266	  static String SelectInst(const GemmNode &op, int block_size, Target target) {
267	    if (op.isWgmma_) {
268	      if (!AllowWgmma(op, block_size, target)) {
269	        FatalWgmmaUnavailable(op, target);
270	      }
271	      return kCudaWGMMA;
272	    }
273	    if (op.isTcgen05_) {
274	      if (!AllowTcgen5Mma(op, target)) {
275	        FatalTcgen5Unavailable(op, target);
276	      }
277	      return kCudaTCGEN05;
278	    }
279	
280	    if (AllowTcgen5Mma(op, target)) {
281	      return kCudaTCGEN05;
282	    }
283	    if (AllowWgmma(op, block_size, target)) {
284	      return kCudaWGMMA;
285	    }
286	    return kCudaMMA;
287	  }
288	
289	  static std::pair<int, int>
290	  ComputeWarpPartition(const GemmWarpPolicyNode &policy, int M, int N,
291	                       int block_size, Target target, String gemm_inst) {
292	    int num_warps = block_size / TargetCudaGetWarpSize(target);
293	    if (gemm_inst == kCudaTCGEN05) {
294	      policy.m_warp = 1;
295	      policy.n_warp = num_warps;
296	      return {1, num_warps};
297	    }
298	    if (gemm_inst == kCudaWGMMA) {
299	      return ComputeWgmmaWarpPartition(policy, M, N, num_warps);
300	    }
301	    int k_n_per_warp = TargetIsVolta(target) ? 16 : 8;
302	    return ComputeDefaultWarpPartition(policy, M, N, num_warps, k_n_per_warp);
303	  }
304	
305	  static bool ReuseExistingSharedLayout(String gemm_inst) {
306	    return gemm_inst == kCudaMMA;
307	  }
308	};
309	
310	} // namespace cuda
311	
312	namespace {
313	
314	bool MatchCudaGemmTarget(Target target) {
315	  return TargetIsCuda(target) || TargetIsCuTeDSL(target);
316	}
317	
318	bool RegisterCudaGemm() {
319	  RegisterGemmImpl(GemmImpl{
320	      "cuda.Gemm",
321	      MatchCudaGemmTarget,
322	      cuda::Gemm::SelectInst,
323	      cuda::Gemm::ComputeWarpPartition,
324	      cuda::Gemm::ReuseExistingSharedLayout,
325	  });
326	  return true;
327	}
328	
329	const bool cuda_gemm_registered = RegisterCudaGemm();
330	
