221	LayoutMap GemmNode::InferLayout(const LayoutInferArgs &layout_args,
222	                                InferLevel level) const {
223	  if (completed_)
224	    return {};
225	  LayoutMap results;
226	  if (const auto f = Function::GetGlobal("tl.gemm.infer_layout")) {
227	    auto inferred_layouts = Downcast<LayoutMap>((*f)(
228	        GetRef<Gemm>(this), layout_args.target, layout_args.thread_bounds));
229	    // For MMA instructions, skip shared buffer layouts that are already
230	    // inferred by a prior operator to avoid layout conflicts when the same
231	    // shared buffer is consumed by multiple gemm ops with different transpose
232	    // semantics. WGMMA/TCGEN5MMA have strict shared memory layout requirements
233	    // and must always set their layouts.
234	    auto block_size = *as_const_int(layout_args.thread_bounds->extent);
235	    String gemm_inst = GetGemmInstructionKey(block_size, layout_args.target);
236	    bool reuse_existing_shared_layout =
237	        ResolveGemmImpl(layout_args.target)
238	            .reuse_existing_shared_layout(gemm_inst);
239	    for (auto kv : inferred_layouts) {
240	      const Buffer &buf = kv.first;
241	      const Layout &layout = kv.second;
242	      if (reuse_existing_shared_layout && IsSharedBuffer(buf) &&
243	          layout_args.layout_map.count(buf)) {
244	        continue;
245	      }
246	      if (auto frag = layout.as<Fragment>()) {
247	        results.Set(buf,
248	                    frag.value()->BindThreadRange(layout_args.thread_bounds));
249	      } else {
250	        results.Set(buf, layout);
251	      }
252	    }
253	  } else {
254	    LOG(FATAL) << "No infer layout function found for gemm";
255	  }
256	
257	  completed_ = true;
258	  return results;
259	}
