41	static Buffer makeBufferWithLayout(const Buffer &buffer, const Layout &layout,
42	                                   Map<Var, Var> &var_remap) {
43	  const auto *ptr_type =
44	      TVM_TYPE_AS(buffer->data->type_annotation, PointerTypeNode);
45	  Type new_type;
46	  // convert fragments to normal local buffer
47	  if (IsFragmentBuffer(buffer)) {
48	    new_type = PointerType(ptr_type->element_type, "local");
49	  } else {
50	    new_type = buffer->data->type_annotation;
51	  }
52	  Var new_var;
53	  if (IsGlobalBuffer(buffer)) {
54	    new_var = buffer->data;
55	  } else {
56	    if (var_remap.count(buffer->data)) {
57	      new_var = var_remap[buffer->data];
58	    } else {
59	      new_var = Var(buffer->data->name_hint, new_type);
60	      var_remap.Set(buffer->data, new_var);
61	    }
62	  }
63	  Array<PrimExpr> layout_shape = layout->OutputShape();
64	  Array<PrimExpr> output_shape = layout_shape;
65	  if (IsSharedBuffer(buffer)) {
66	    int replicate_extent = 1;
67	    Array<PrimExpr> buffer_shape = buffer->shape;
68	    int buffer_extent = 1;
69	    int layout_extent = 1;
70	    for (size_t i = 0; i < buffer_shape.size(); i++) {
71	      auto shape = buffer_shape[i].as<IntImmNode>();
72	      buffer_extent *= shape->value;
73	    }
74	    for (size_t i = 0; i < layout_shape.size(); i++) {
75	      auto shape = layout_shape[i].as<IntImmNode>();
76	      ICHECK(shape) << "Layout output shape must be constant integer, but got: "
77	                    << layout_shape[i];
78	      layout_extent *= shape->value;
79	    }
80	    replicate_extent = buffer_extent / layout_extent;
81	    if (replicate_extent > 1) {
82	      output_shape.insert(output_shape.begin(), replicate_extent);
83	    }
84	  }
85	  return Buffer(new_var, buffer->dtype, output_shape, {}, buffer->elem_offset,
86	                buffer->name, buffer->data_alignment, buffer->offset_factor,
87	                buffer->buffer_type);
88	}
89	
90	// The function `makeBufferWithLayout` creates a new Buffer object based on the
91	// given buffer and layout. It handles remapping of buffer variables, adjusts
92	// the storage scope if needed (e.g., from "local.fragment" to "local"), and
93	// computes the output shape according to the layout. For shared memory buffers,
94	// it also handles replication if the buffer's extent is larger than the
95	// layout's extent.
96	class LayoutRemapRewriter : public arith::IRMutatorWithAnalyzer {
97	public:
98	  static Stmt Substitute(Stmt stmt, Map<Buffer, Layout> layout_remap) {
99	    arith::Analyzer analyzer;
100	    LayoutRemapRewriter substituter(&analyzer);
101	    substituter.layout_remap_ = std::move(layout_remap);
102	    return substituter.VisitStmt(stmt);
103	  }
104	
105	private:
106	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
107	
108	  Stmt VisitStmt_(const SBlockNode *op) final {
109	    auto block = Downcast<SBlock>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
110	    if (op->annotations.count(attr::kLayoutMap)) {
111	      block.CopyOnWrite()->annotations.Set(attr::kLayoutMap, layout_remap_);
112	    }
113	    return block;
114	  }
115	
116	  Map<Buffer, Layout> layout_remap_;
117	};
