119	/*!
120	 * \brief A class that rewrites buffer references in a statement based on a
121	 * given buffer remapping.
122	 *
123	 * This class is used to update buffer references in a statement after buffer
124	 * transformations have been applied. It specifically handles the remapping of
125	 * padding annotations.
126	 */
127	class RemapBufferRewriter : public arith::IRMutatorWithAnalyzer {
128	public:
129	  /*!
130	   * \brief Substitute buffer references in a statement based on a given buffer
131	   * remapping. \param stmt The statement to rewrite. \param buffer_remap A map
132	   * from old buffers to new buffers. \return The rewritten statement.
133	   */
134	  static Stmt Substitute(const Stmt &stmt, Map<Buffer, Buffer> buffer_remap) {
135	    arith::Analyzer analyzer;
136	    RemapBufferRewriter substituter(&analyzer);
137	    substituter.remap_ = std::move(buffer_remap);
138	    return substituter.VisitStmt(stmt);
139	  }
140	
141	private:
142	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
143	
144	  Stmt VisitStmt_(const SBlockNode *op) final {
145	    if (op->annotations.count(attr::kSafeValueMap)) {
146	      return RewritePaddingMap(op);
147	    }
148	    return IRMutatorWithAnalyzer::VisitStmt_(op);
149	  }
150	
151	  Stmt RewritePaddingMap(const SBlockNode *op) {
152	    auto safe_value_map = op->annotations.Get(attr::kSafeValueMap);
153	    if (!safe_value_map) {
154	      LOG(FATAL) << "Padding map annotation is missing";
155	    }
156	
157	    Map<Var, Var> var_remap = CreateVarRemap();
158	    Map<Var, PrimExpr> new_safe_value_map = RemapPaddingMap(
159	        Downcast<Map<Var, PrimExpr>>(safe_value_map.value()), var_remap);
160	
161	    auto block = Downcast<SBlock>(IRMutatorWithAnalyzer::VisitStmt_(op));
162	    auto block_ptr = block.CopyOnWrite();
163	    block_ptr->annotations.Set(attr::kSafeValueMap, new_safe_value_map);
164	    return block;
165	  }
166	
167	  Map<Var, Var> CreateVarRemap() const {
168	    Map<Var, Var> var_remap;
169	    for (const auto &[buffer, remapped] : remap_) {
170	      var_remap.Set(buffer->data, remapped->data);
171	    }
172	    return var_remap;
173	  }
174	
175	  Map<Var, PrimExpr> RemapPaddingMap(const Map<Var, PrimExpr> &safe_value_map,
176	                                     const Map<Var, Var> &var_remap) const {
177	    Map<Var, PrimExpr> new_safe_value_map;
178	    for (const auto &[var, padding] : safe_value_map) {
179	      if (var_remap.count(var)) {
180	        new_safe_value_map.Set(var_remap.at(var), padding);
181	      } else {
182	        new_safe_value_map.Set(var, padding);
183	      }
184	    }
185	    return new_safe_value_map;
186	  }
187	
188	  Map<Buffer, Buffer> remap_;
189	};
