208	    ICHECK(target.defined()) << "LowerTileOpPass: Require the target attribute";
209	    substituter.target_ = target.value();
210	    PrimFuncNode *fptr = f.CopyOnWrite();
211	    fptr->body = substituter.VisitStmt(f->body);
212	    fptr->body =
213	        RemapBufferRewriter::Substitute(fptr->body, substituter.buffer_remap_);
214	    fptr->body =
215	        LayoutRemapRewriter::Substitute(fptr->body, substituter.layout_remap_);
216	    // Record whether TMA was actually used as a PrimFunc attribute so that
217	    // later phases (OptimizeForTarget) can choose the right pass pipeline
218	    // without relying on pass-context side-channel mutation.
219	    f = WithAttr(std::move(f), kHasTMA, Bool(substituter.has_tma_));
220	    // Propagate per-buffer shared-memory alignment requirements collected
221	    // during lowering (swizzle-dependent TMA/MMA constraints) so that
222	    // MergeSharedMemoryAllocations can honor them when laying out the merged
223	    // dynamic shared memory buffer.
224	    if (!substituter.smem_alignment_map_.empty()) {
225	      f = WithAttr(std::move(f), kSmemAlignmentMap,
226	                   substituter.smem_alignment_map_);
227	    }
228	    fptr = f.CopyOnWrite();
229	
230	    // If any TMA copies allocated mbarriers, inject the barrier buffer
231	    // into the tilelang_root block with a barrier_init annotation.
232	    // Pipeline buffer versioning expands it for pipelining, and
233	    // LowerSharedBarrier will process it into ptx_init_barrier_thread_count.
234	    if (substituter.mbarrier_count_ > 0) {
235	      ICHECK(substituter.mbarrier_buffer_.defined())
236	          << "mbarrier_buffer_ must have been created by alloc_mbarrier "
237	             "callback";
238	      Buffer mbar_buf = substituter.mbarrier_buffer_.value();
239	      // Update buffer shape in-place to final count. We use const_cast
240	      // because CopyOnWrite would create a new BufferNode, breaking identity
241	      // with BufferLoad references already in the body. Pipeline buffer
242	      // versioning relies on buffer identity to remap accesses correctly.
243	      const_cast<BufferNode *>(mbar_buf.get())->shape = {
244	          IntImm(DataType::Int(32), substituter.mbarrier_count_)};
245	
246	      Array<PrimExpr> counts;
247	      counts.reserve(substituter.mbarrier_count_);
248	      for (auto c : substituter.mbarrier_arrive_counts_)
249	        counts.push_back(IntImm(DataType::Int(32), c));
250	
251	      // Walk the body to find the inner "tilelang_root" SBlockRealize
252	      // (inside the threadIdx.x scope) and inject the barrier buffer
253	      // + barrier_init annotation.
254	      struct RootBlockInjector : public StmtMutator {
255	        Buffer barrier_buf;
256	        Array<PrimExpr> arrive_counts;
257	        bool injected{false};
258	
259	        Stmt VisitStmt_(const SBlockRealizeNode *op) final {
260	          if (injected)
261	            return StmtMutator::VisitStmt_(op);
262	          if (op->block->name_hint == "root") {
263	            return StmtMutator::VisitStmt_(op);
264	          }
265	          injected = true;
266	          SBlock block = op->block;
267	          auto block_ptr = block.CopyOnWrite();
268	          block_ptr->alloc_buffers.push_back(barrier_buf);
269	          Map<Var, Array<PrimExpr>> barrier_init_map;
270	          if (block_ptr->annotations.count("barrier_init")) {
271	            barrier_init_map = Downcast<Map<Var, Array<PrimExpr>>>(
272	                block_ptr->annotations.at("barrier_init"));
273	          }
274	          barrier_init_map.Set(barrier_buf->data, arrive_counts);
275	          block_ptr->annotations.Set("barrier_init", barrier_init_map);
276	          auto realize = GetRef<SBlockRealize>(op);
277	          auto realize_ptr = realize.CopyOnWrite();
278	          realize_ptr->block = block;
279	          return realize;
280	        }
281	      };
282	
283	      RootBlockInjector injector;
284	      injector.barrier_buf = mbar_buf;
285	      injector.arrive_counts = counts;
286	      fptr->body = injector(fptr->body);
287	      ICHECK(injector.injected)
288	          << "Failed to find root SBlockRealize for barrier injection";
289	    }
290	
291	    return f;
292	  }
