294	private:
295	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
296	
297	  Stmt VisitStmt_(const SBlockNode *op) final {
298	    Map<String, Any> previous_block_annotations = block_annotations_;
299	    Map<Var, PrimExpr> previous_safe_value_map = safe_value_map_;
300	    block_annotations_ = op->annotations;
301	
302	    // Record the mapping from buffer data var to buffer for later lookup
303	    for (auto buffer : op->alloc_buffers) {
304	      buffer_map_.insert({buffer->data, buffer});
305	    }
306	    for (auto match_buffer : op->match_buffers) {
307	      buffer_map_.insert({match_buffer->buffer->data, match_buffer->buffer});
308	      buffer_data_to_buffer_.Set(match_buffer->buffer->data,
309	                                 match_buffer->buffer);
310	    }
311	    for (auto buffer : op->alloc_buffers) {
312	      buffer_data_to_buffer_.Set(buffer->data, buffer);
313	    }
314	    RecordSafeValueAnnotations(op);
315	    if (!safe_value_map_.empty()) {
316	      block_annotations_.Set(attr::kSafeValueMap, safe_value_map_);
317	    } else {
318	      block_annotations_.erase(attr::kSafeValueMap);
319	    }
320	    Map<Var, Layout> vmap;
321	    if (op->annotations.count(attr::kLayoutMap)) {
322	      auto layout_map = op->annotations.at(attr::kLayoutMap)
323	                            .as<Map<Buffer, Layout>>()
324	                            .value();
325	      for (auto [buffer, layout] : layout_map) {
326	        buffer_remap_.Set(buffer,
327	                          makeBufferWithLayout(buffer, layout, var_remap_));
328	        layout_map_.Set(buffer, layout);
329	      }
330	    }
331	    // Extract cluster_size from cluster_dims annotation
332	    if (op->annotations.count("cluster_dims")) {
333	      if (auto arr =
334	              op->annotations.Get("cluster_dims")->try_cast<Array<Integer>>()) {
335	        int sz = 1;
336	        for (auto d : arr.value())
337	          sz *= static_cast<int>(d->value);
338	        cluster_size_ = sz;
339	      }
340	    }
341	    // Begin a new workspace collection frame for this block scope
342	    workspace_stack_.emplace_back();
343	
344	    auto block = Downcast<SBlock>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
345	    auto block_ptr = block.CopyOnWrite();
346	    for (size_t i = 0; i < block->alloc_buffers.size(); i++) {
347	      auto buffer = block->alloc_buffers[i];
348	      if (buffer_remap_.count(buffer)) {
349	        block_ptr->alloc_buffers.Set(i, buffer_remap_[buffer]);
350	      } else if (IsFragmentBuffer(buffer)) {
351	        const auto *ptr_type =
352	            TVM_TYPE_AS(buffer->data->type_annotation, PointerTypeNode);
353	        Type new_type = PointerType(ptr_type->element_type, "local");
354	        Var new_var;
355	        if (var_remap_.count(buffer->data)) {
356	          new_var = var_remap_[buffer->data];
357	        } else {
358	          new_var = Var(buffer->data->name_hint, new_type);
359	          var_remap_.Set(buffer->data, new_var);
360	        }
361	        Buffer new_buf(new_var, buffer->dtype, buffer->shape, buffer->strides,
362	                       buffer->elem_offset, buffer->name,
363	                       buffer->data_alignment, buffer->offset_factor,
364	                       buffer->buffer_type);
365	        buffer_remap_.Set(buffer, new_buf);
366	        block_ptr->alloc_buffers.Set(i, new_buf);
367	      }
368	    }
369	    // Attach any workspaces requested within this block to its alloc_buffers
370	    if (!workspace_stack_.empty()) {
371	      for (const auto &buffer : workspace_stack_.back()) {
372	        block_ptr->alloc_buffers.push_back(buffer);
373	      }
374	      workspace_stack_.pop_back();
375	    }
376	
377	    // Apply arrive-count overrides before LowerSharedBarrier consumes them.
378	    if (!barrier_arrive_updates_.empty() &&
379	        block->annotations.count("barrier_init")) {
380	      auto barrier_init_map = Downcast<Map<Var, Array<PrimExpr>>>(
381	          block->annotations.Get("barrier_init").value());
382	      bool updated = false;
383	      for (auto it = barrier_arrive_updates_.begin();
384	           it != barrier_arrive_updates_.end();) {
385	        if (barrier_init_map.count(it->first)) {
386	          auto old_counts = barrier_init_map.at(it->first);
387	          Array<PrimExpr> new_counts;
388	          for (size_t i = 0; i < old_counts.size(); i++) {
389	            new_counts.push_back(it->second);
390	          }
391	          barrier_init_map.Set(it->first, new_counts);
392	          updated = true;
393	          it = barrier_arrive_updates_.erase(it);
394	        } else {
395	          ++it;
396	        }
397	      }
398	      if (updated) {
399	        block_ptr->annotations.Set("barrier_init", barrier_init_map);
400	      }
401	    }
402	
403	    block_annotations_ = std::move(previous_block_annotations);
404	    safe_value_map_ = std::move(previous_safe_value_map);
405	    return block;
406	  }
407	
408	  int CheckAndGetBufferRowSize(const Buffer &buffer) {
409	    ICHECK(buffer->shape.size() >= 2)
410	        << "The dimension of Buffer \"" << buffer->name << "\" with shape "
411	        << buffer->shape << " should be at least 2";
412	
413	    auto dim = buffer->shape.size();
414	    auto buffer_row_size = buffer->shape[dim - 1].as<IntImmNode>()->value;
415	    return buffer_row_size;
416	  }
417	
418	  struct AccessPtrResult {
419	    PrimExpr expr;
420	    bool rewritten{false};
421	  };
422	
423	  AccessPtrResult
424	  HandleAccessPtrAndOffset(const PrimExpr &access_ptr,
425	                           const Optional<PrimExpr> &offset = std::nullopt,
426	                           DataType dtype = DataType::Int(32)) {
427	    AccessPtrResult result{access_ptr, false};
428	    // The 2th arg of T.tvm_access_ptr call is offset, we set it to 0 and
429	    // accumulate it to smem_offset
430	    ICHECK(access_ptr->IsInstance<CallNode>())
431	        << "Invalid access ptr for permuted layout: " << access_ptr;
432	    auto access_ptr_call = Downcast<Call>(access_ptr);
433	    if (access_ptr_call->op.same_as(builtin::tvm_access_ptr())) {
434	      // tvm_access_ptr format: (dtype, data, offset, extent, rw_mask)
435	      auto buffer_var = Downcast<Var>(access_ptr_call->args[1]);
436	
437	      // Find original buffer from buffer_map_ using buffer_var
438	      auto it = buffer_map_.find(buffer_var);
439	      if (it == buffer_map_.end()) {
440	        // If not found, buffer_var might be a new var after remap
441	        // Do reverse lookup in var_remap_
442	        for (const auto &[old_var, new_var] : var_remap_) {
443	          if (new_var.same_as(buffer_var)) {
444	            it = buffer_map_.find(old_var);
445	            break;
446	          }
447	        }
448	      }
449	
450	      if (it == buffer_map_.end()) {
451	        return result; // Buffer not found, no transformation needed
452	      }
453	
454	      Buffer original_buffer = it->second;
455	
456	      // Check if this buffer has a layout
457	      if (!layout_map_.count(original_buffer)) {
458	        return result; // No layout, no transformation needed
459	      }
460	
461	      Layout layout = layout_map_[original_buffer];
462	      Buffer new_buffer = buffer_remap_[original_buffer];
463	
464	      // In TMA context, swizzle is encoded in TMA descriptor parameters
465	      // rather than in memory indices, so we only update buffer data
466	      // without recomputing indices.
467	      if (in_tma_context_) {
468	        Array<PrimExpr> new_args = access_ptr_call->args;
469	        new_args.Set(1, new_buffer->data); // Only replace data var
470	        layout_remap_.Set(new_buffer, layout);
471	        result.rewritten = true;
472	        result.expr =
473	            Call(access_ptr_call->dtype, access_ptr_call->op, new_args,
474	                 access_ptr_call->annotations, access_ptr_call->span);
475	        return result;
476	      }
477	
478	      // Get the offset from tvm_access_ptr args[2]
479	      PrimExpr elem_offset = access_ptr_call->args[2];
480	      if (offset.defined()) {
481	        elem_offset = elem_offset + offset.value();
482	      }
483	      // Get original and new buffer shapes
484	      Array<PrimExpr> old_shape = original_buffer->shape;
485	      Array<PrimExpr> new_shape = new_buffer->shape;
486	      // Convert linear offset to multi-dimensional indices
487	      Array<PrimExpr> multi_dim_indices;
488	      PrimExpr remaining_offset = elem_offset;
489	      for (int i = static_cast<int>(old_shape.size()) - 1; i >= 0; --i) {
490	        multi_dim_indices.insert(
491	            multi_dim_indices.begin(),
492	            analyzer_->Simplify(floormod(remaining_offset, old_shape[i])));
493	        remaining_offset =
494	            analyzer_->Simplify(floordiv(remaining_offset, old_shape[i]));
495	      }
496	      // Apply layout transformation
497	      auto forward_indices = layout->Forward(multi_dim_indices);
498	      PrimExpr new_offset = 0;
499	      PrimExpr stride_offset = 1;
500	      for (int i = static_cast<int>(new_shape.size()) - 1; i >= 0; --i) {
501	        new_offset += forward_indices[i] * stride_offset;
502	        stride_offset *= new_shape[i];
503	      }
504	      new_offset = analyzer_->Simplify(new_offset);
505	      Array<PrimExpr> new_indices;
506	      layout_remap_.Set(new_buffer, layout);
507	
508	      // Build new tvm_access_ptr call with new buffer and offset
509	      Array<PrimExpr> new_args = access_ptr_call->args;
510	      new_args.Set(1, new_buffer->data); // Replace data var
511	      new_args.Set(2, new_offset);       // Replace offset
512	      result.rewritten = true;
513	      result.expr = Call(access_ptr_call->dtype, access_ptr_call->op, new_args,
514	                         access_ptr_call->annotations, access_ptr_call->span);
515	      return result;
516	    } else if (access_ptr_call->op.same_as(builtin::address_of())) {
517	      Optional<PrimExpr> resolved = ResolveBufferLoad(access_ptr_call->args[0]);
518	      ICHECK(resolved.defined())
519	          << "Invalid access op for permuted layout: " << access_ptr;
520	      PrimExpr load_expr = resolved.value();
521	      if (!load_expr.same_as(access_ptr_call->args[0])) {
522	        auto node = access_ptr_call.CopyOnWrite();
523	        node->args.Set(0, load_expr);
524	        access_ptr_call =
525	            Call(access_ptr_call->dtype, access_ptr_call->op, {load_expr},
526	                 access_ptr_call->annotations, access_ptr_call->span);
527	      }
528	      BufferLoad load = Downcast<BufferLoad>(access_ptr_call->args[0]);
529	      Array<PrimExpr> indices = load->indices;
530	      Array<PrimExpr> old_shape = load->buffer->shape;
531	
532	      ICHECK_EQ(indices.size(), old_shape.size())
533	          << "Indices size and shape size must match for general N-dimensional "
534	             "buffer "
535	          << "but got indices size: " << indices.size()
536	          << " and shape size: " << old_shape.size();
537	
538	      Buffer remap_key = FindRemapBuffer(load->buffer).value_or(load->buffer);
539	      Optional<Layout> layout = FindLayout(remap_key);
540	      if (!layout.defined() || !buffer_map_.count(remap_key->data)) {
541	        return result;
542	      }
543	      auto new_buffer = buffer_remap_.count(remap_key)
544	                            ? buffer_remap_[remap_key]
545	                            : load->buffer;
546	      auto new_shape = new_buffer->shape;
547	
548	      // In TMA context, swizzle is encoded in TMA descriptor parameters
549	      // rather than in memory indices, so we only update buffer data
550	      // without recomputing indices.
551	      if (in_tma_context_) {
552	        Array<PrimExpr> new_args = {BufferLoad(new_buffer, indices)};
553	        if (buffer_remap_.count(remap_key)) {
554	          layout_remap_.Set(new_buffer, layout.value());
555	        }
556	        result.rewritten = true;
557	        result.expr =
558	            Call(access_ptr_call->dtype, access_ptr_call->op, new_args,
559	                 access_ptr_call->annotations, access_ptr_call->span);
560	        return result;
561	      }
562	
563	      PrimExpr elem_offset = 0;
564	      PrimExpr stride = 1;
565	
566	      for (int i = static_cast<int>(old_shape.size()) - 1; i >= 0; --i) {
567	        elem_offset += indices[i] * stride;
568	        stride *= old_shape[i];
569	      }
570	
571	      PrimExpr smem_offset =
572	          elem_offset + (offset.defined() ? offset.value() : 0);
573	
574	      auto buffer_map_iter = buffer_map_.find(Downcast<Var>(remap_key->data));
575	
576	      int buffer_row_size = CheckAndGetBufferRowSize(buffer_map_iter->second);
577	      (void)buffer_row_size;
578	
579	      // Convert offset to target-dimension, reindex it and convert it back
580	      Array<PrimExpr> multi_dim_indices;
581	      PrimExpr remaining_offset = smem_offset;
582	
583	      for (int i = static_cast<int>(old_shape.size()) - 1; i >= 0; --i) {
584	        multi_dim_indices.insert(multi_dim_indices.begin(),
585	                                 floormod(remaining_offset, old_shape[i]));
586	        remaining_offset = floordiv(remaining_offset, old_shape[i]);
587	      }
588	
589	      auto forward_indices = layout.value()->Forward(multi_dim_indices);
590	      PrimExpr new_offset = 0;
591	      PrimExpr stride_offset = 1;
592	      for (int i = static_cast<int>(new_shape.size()) - 1; i >= 0; --i) {
593	        new_offset += forward_indices[i] * stride_offset;
594	        stride_offset *= new_shape[i];
595	      }
596	      new_offset = analyzer_->Simplify(new_offset);
597	
598	      Array<PrimExpr> new_indices;
599	      for (int i = static_cast<int>(new_shape.size()) - 1; i >= 0; --i) {
600	        new_indices.insert(new_indices.begin(),
601	                           floormod(new_offset, new_shape[i]));
602	        new_offset = floordiv(new_offset, new_shape[i]);
603	      }
604	
605	      Array<PrimExpr> new_args = {BufferLoad(new_buffer, new_indices)};
606	      if (buffer_remap_.count(remap_key)) {
607	        layout_remap_.Set(new_buffer, layout.value());
608	      }
609	      result.rewritten = true;
610	      result.expr = Call(access_ptr_call->dtype, access_ptr_call->op, new_args,
611	                         access_ptr_call->annotations, access_ptr_call->span);
612	      return result;
613	    } else if (access_ptr_call->op.same_as(tl::access_ptr())) {
614	      // tl.access_ptr format: (base_load, extent, rw_mask)
615	      ICHECK_EQ(access_ptr_call->args.size(), 3U)
616	          << "tl.access_ptr expects 3 args: (BufferLoad, extent, rw_mask)";
617	      Optional<PrimExpr> resolved = ResolveBufferLoad(access_ptr_call->args[0]);
618	      ICHECK(resolved.defined())
619	          << "Invalid tl.access_ptr argument for permuted layout: "
620	          << access_ptr_call->args[0];
621	      PrimExpr load_expr = resolved.value();
622	      if (!load_expr.same_as(access_ptr_call->args[0])) {
623	        Array<PrimExpr> new_args = access_ptr_call->args;
624	        new_args.Set(0, load_expr);
625	        access_ptr_call =
626	            Call(access_ptr_call->dtype, access_ptr_call->op, new_args,
627	                 access_ptr_call->annotations, access_ptr_call->span);
628	      }
629	
630	      BufferLoad load = Downcast<BufferLoad>(access_ptr_call->args[0]);
631	      PrimExpr extent = access_ptr_call->args[1];
632	      PrimExpr rw_mask = access_ptr_call->args[2];
633	
634	      Array<PrimExpr> indices = load->indices;
635	      Array<PrimExpr> old_shape = load->buffer->shape;
636	
637	      ICHECK_EQ(indices.size(), old_shape.size())
638	          << "Indices size and shape size must match for general N-dimensional "
639	             "buffer "
640	          << "but got indices size: " << indices.size()
641	          << " and shape size: " << old_shape.size();
642	
643	      Buffer remap_key = FindRemapBuffer(load->buffer).value_or(load->buffer);
644	      Optional<Layout> layout = FindLayout(remap_key);
645	      if (!layout.defined() || !buffer_map_.count(remap_key->data)) {
646	        return result;
647	      }
648	      auto new_buffer = buffer_remap_.count(remap_key)
649	                            ? buffer_remap_[remap_key]
650	                            : load->buffer;
651	      auto new_shape = new_buffer->shape;
652	
653	      // In TMA context, swizzle is encoded in TMA descriptor parameters
654	      // rather than in memory indices, so we only update buffer data
655	      // without recomputing indices.
656	      if (in_tma_context_) {
657	        Array<PrimExpr> new_args = {BufferLoad(new_buffer, indices), extent,
658	                                    rw_mask};
659	        if (buffer_remap_.count(remap_key)) {
660	          layout_remap_.Set(new_buffer, layout.value());
661	        }
662	        result.rewritten = true;
663	        result.expr =
664	            Call(access_ptr_call->dtype, access_ptr_call->op, new_args,
665	                 access_ptr_call->annotations, access_ptr_call->span);
666	        return result;
667	      }
668	
669	      PrimExpr elem_offset = 0;
670	      PrimExpr stride = 1;
671	      for (int i = static_cast<int>(old_shape.size()) - 1; i >= 0; --i) {
672	        elem_offset += indices[i] * stride;
673	        stride *= old_shape[i];
674	      }
675	
676	      PrimExpr smem_offset =
677	          elem_offset + (offset.defined() ? offset.value() : 0);
678	
679	      auto buffer_map_iter = buffer_map_.find(Downcast<Var>(remap_key->data));
680	      int buffer_row_size = CheckAndGetBufferRowSize(buffer_map_iter->second);
681	      (void)buffer_row_size;
682	
683	      // Convert offset to target-dimension, reindex it and convert it back
684	      Array<PrimExpr> multi_dim_indices;
685	      PrimExpr remaining_offset = smem_offset;
686	      for (int i = static_cast<int>(old_shape.size()) - 1; i >= 0; --i) {
687	        multi_dim_indices.insert(multi_dim_indices.begin(),
688	                                 floormod(remaining_offset, old_shape[i]));
689	        remaining_offset = floordiv(remaining_offset, old_shape[i]);
690	      }
691	
692	      auto forward_indices = layout.value()->Forward(multi_dim_indices);
693	      PrimExpr new_offset = 0;
694	      PrimExpr stride_offset = 1;
695	      for (int i = static_cast<int>(new_shape.size()) - 1; i >= 0; --i) {
696	        new_offset += forward_indices[i] * stride_offset;
697	        stride_offset *= new_shape[i];
698	      }
699	      new_offset = analyzer_->Simplify(new_offset);
700	
701	      Array<PrimExpr> new_indices;
702	      for (int i = static_cast<int>(new_shape.size()) - 1; i >= 0; --i) {
703	        new_indices.insert(new_indices.begin(),
704	                           floormod(new_offset, new_shape[i]));
705	        new_offset = floordiv(new_offset, new_shape[i]);
706	      }
707	
708	      Array<PrimExpr> new_args = {BufferLoad(new_buffer, new_indices), extent,
709	                                  rw_mask};
710	      if (buffer_remap_.count(remap_key)) {
711	        layout_remap_.Set(new_buffer, layout.value());
712	      }
713	      result.rewritten = true;
714	      result.expr = Call(access_ptr_call->dtype, access_ptr_call->op, new_args,
715	                         access_ptr_call->annotations, access_ptr_call->span);
716	      return result;
717	    } else {
718	      LOG(FATAL) << "Invalid access op for permuted layout: " << access_ptr;
719	    }
720	
721	    return result;
722	  }
723	
724	  Optional<PrimExpr> ResolveBufferLoad(const PrimExpr &expr) const {
725	    if (expr->IsInstance<BufferLoadNode>()) {
726	      return expr;
727	    }
728	    if (const auto *var_node = expr.as<VarNode>()) {
729	      Var var = GetRef<Var>(var_node);
730	      auto it = bind_var_to_expr_.find(var);
731	      if (it != bind_var_to_expr_.end()) {
