738	  Optional<Buffer> FindRemapBuffer(const Buffer &buffer) const {
739	    if (buffer_remap_.count(buffer)) {
740	      return buffer;
741	    }
742	    auto it = buffer_map_.find(buffer->data);
743	    if (it != buffer_map_.end() && buffer_remap_.count(it->second)) {
744	      return it->second;
745	    }
746	    for (const auto &kv : buffer_remap_) {
747	      if (kv.first->data.same_as(buffer->data)) {
748	        return kv.first;
749	      }
750	      if (kv.first->name == buffer->name) {
751	        return kv.first;
752	      }
753	    }
754	    return Optional<Buffer>();
755	  }
