762	    if (it != buffer_map_.end() && layout_map_.count(it->second)) {
763	      return layout_map_[it->second];
764	    }
765	    for (const auto &kv : layout_map_) {
766	      if (kv.first->data.same_as(buffer->data)) {
767	        return kv.second;
768	      }
769	      if (kv.first->name == buffer->name) {
770	        return kv.second;
771	      }
