994	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
995	    auto load = Downcast<BufferLoad>(IRMutatorWithAnalyzer::VisitExpr_(op));
996	    if (is_ptx_) {
997	      return load;
998	    }
999	    auto buffer = load->buffer;
1000	    if (buffer_remap_.count(buffer)) {
1001	      auto new_indices = layout_map_[buffer]->Forward(load->indices);
1002	      auto new_buffer = buffer_remap_[load->buffer];
1003	      layout_remap_.Set(new_buffer, layout_map_[load->buffer]);
1004	      return BufferLoad(new_buffer, new_indices);
1005	    } else if (var_remap_.count(buffer->data)) {
1006	      auto new_buffer = Buffer(
1007	          var_remap_[buffer->data], buffer->dtype, buffer->shape,
1008	          buffer->strides, buffer->elem_offset, buffer->name,
1009	          buffer->data_alignment, buffer->offset_factor, buffer->buffer_type);
1010	      return BufferLoad(new_buffer, load->indices);
1011	    }
1012	    return load;
1013	  }
