1044	    PrimExpr value = this->VisitExpr(op->value);
1045	    bool recorded = false;
1046	    if (value->IsInstance<BufferLoadNode>()) {
1047	      bind_var_to_expr_[op->var] = value;
1048	      recorded = true;
