1062	  /**
1063	   * @brief Handle an Evaluate node, lowering a detected tile operator to TIR.
1064	   *
1065	   * This visit implementation detects whether the Evaluate node represents a
1066	   * tile operator invocation (via ParseOperator). If no tile operator is found
1067	   * or the call targets a global function, the node is delegated to the base
1068	   * visitor.
1069	   *
1070	   * When a tile operator is present, the method:
1071	   * - Builds a workspace-allocation callback that creates a dynamic shared
1072	   * buffer named "workspace" (storage scope "shared.dyn") and returns its write
1073	   *   access pointer.
1074	   * - Determines thread bounds for lowering from the analyzer's constant-int
1075	   *   information for the thread binding; if unavailable, a default range
1076	   *   [0,1) is used.
1077	   * - Invokes tile_op->Lower(...) with LowerArgs containing target, thread
1078	   *   bounds, the logical thread index, the workspace callback, layout and
1079	   *   buffer remap maps, and the list of GEMM-involved buffer vars; the
1080	   *   analyzer is passed through for use during lowering.
1081	   *
1082	   * The lowered statement returned by the operator is then visited by the base
1083	   * IRMutatorWithAnalyzer and that result is returned.
1084	   *
1085	   * @return Stmt The (possibly transformed) statement after lowering or base
1086	   * visitor processing.
1087	   */
1088	  Stmt VisitStmt_(const AllocBufferNode *op) final {
1089	    auto buffer = op->buffer;
1090	    if (buffer_remap_.count(buffer)) {
1091	      auto node = Downcast<AllocBuffer>(IRMutatorWithAnalyzer::VisitStmt_(op));
1092	      node.CopyOnWrite()->buffer = buffer_remap_[buffer];
1093	      return std::move(node);
1094	    }
1095	    if (IsFragmentBuffer(buffer)) {
1096	      const auto *ptr_type =
1097	          TVM_TYPE_AS(buffer->data->type_annotation, PointerTypeNode);
1098	      Type new_type = PointerType(ptr_type->element_type, "local");
1099	      Var new_var;
1100	      if (var_remap_.count(buffer->data)) {
1101	        new_var = var_remap_[buffer->data];
1102	      } else {
1103	        new_var = Var(buffer->data->name_hint, new_type);
1104	        var_remap_.Set(buffer->data, new_var);
1105	      }
1106	      Buffer new_buf(new_var, buffer->dtype, buffer->shape, buffer->strides,
1107	                     buffer->elem_offset, buffer->name, buffer->data_alignment,
1108	                     buffer->offset_factor, buffer->buffer_type);
1109	      buffer_remap_.Set(buffer, new_buf);
1110	      auto node = Downcast<AllocBuffer>(IRMutatorWithAnalyzer::VisitStmt_(op));
1111	      node.CopyOnWrite()->buffer = new_buf;
1112	      return std::move(node);
1113	    }
1114	    return IRMutatorWithAnalyzer::VisitStmt_(op);
1115	  }
1116	
1117	  Stmt VisitStmt_(const EvaluateNode *op) final {
1118	    const CallNode *call = op->value.as<CallNode>();
1119	    // Do not analysis the call node to the global function.
1120	    if (call && call->op.as<GlobalVarNode>())
1121	      return Downcast<Evaluate>(IRMutatorWithAnalyzer::VisitStmt_(op));
1122	
1123	    auto tile_op = ParseOperator(GetRef<Stmt>(op), block_annotations_);
1124	    if (!tile_op.defined())
1125	      return IRMutatorWithAnalyzer::VisitStmt_(op);
1126	
1127	    Range thread_bounds = CurrentThreadBounds();
1128	
1129	    // Convert bind_var_to_expr_ to Map<Var, PrimExpr> for LowerArgs
1130	    Map<Var, PrimExpr> bind_var_to_expr;
1131	    for (const auto &[var, expr] : bind_var_to_expr_) {
1132	      bind_var_to_expr.Set(var, expr);
1133	    }
1134	
1135	    AddWorkspaceCallback add_workspace_callback = [this](int num_elem,
1136	                                                         DataType dtype) {
1137	      auto workspace =
1138	          decl_buffer({PrimExpr(num_elem)}, dtype, "workspace", "shared.dyn");
1139	      // Record workspace under the innermost block scope so its lifetime
1140	      // covers the statements that requested it and does not sink into
1141	      // subsequently created inner blocks (e.g., GEMM macro blocks).
1142	      if (!workspace_stack_.empty()) {
1143	        workspace_stack_.back().push_back(workspace);
1144	      } else {
1145	        // Fallback: create a temporary frame (should be rare)
1146	        workspace_stack_.emplace_back(Array<Buffer>{workspace});
1147	      }
1148	      return workspace.access_ptr(2); // write
1149	    };
1150	
1151	    AllocMBarrierCallback mbarrier_callback =
1152	        [this](int arrive_count, std::optional<std::string> name) -> int {
1153	      if (!mbarrier_buffer_.defined()) {
1154	        mbarrier_buffer_ =
1155	            CreateMBarrierBuffer(name.value_or(injected_mbarrier_name_), 1);
1156	      }
1157	      int id = mbarrier_count_++;
1158	      mbarrier_arrive_counts_.push_back(arrive_count);
1159	      return id;
1160	    };
1161	
1162	    UpdateBarrierArriveCallback barrier_arrive_callback = [this](Var data_var,
1163	                                                                 PrimExpr n) {
1164	      barrier_arrive_updates_[data_var] = n;
1165	    };
1166	
1167	    RequireSmemAlignmentCallback require_smem_alignment_callback =
1168	        [this](Var data_var, int alignment) {
1169	          String key = data_var->name_hint;
1170	          auto it = smem_alignment_map_.find(key);
1171	          int64_t prev =
1172	              it != smem_alignment_map_.end() ? (*it).second->value : 0;
1173	          if (alignment > prev) {
1174	            smem_alignment_map_.Set(key, IntImm(DataType::Int(32), alignment));
1175	          }
1176	        };
1177	
1178	    LowerArgs lower_args;
1179	    lower_args.target = target_;
1180	    lower_args.thread_bounds = thread_bounds;
1181	    lower_args.thread_index = CurrentThreadIndex();
1182	    lower_args.layout_map = layout_map_;
1183	    lower_args.buffer_remap = buffer_remap_;
1184	    lower_args.bind_var_to_expr = bind_var_to_expr;
1185	    lower_args.mbar_phase_expr = loop_mbar_phase_stack_.empty()
1186	                                     ? PrimExpr(IntImm(DataType::Int(32), 0))
1187	                                     : loop_mbar_phase_stack_.back();
1188	    lower_args.mbarrier_buffer = &mbarrier_buffer_;
1189	    lower_args.cluster_size = cluster_size_;
1190	    lower_args.add_workspace = add_workspace_callback;
1191	    lower_args.alloc_mbarrier = mbarrier_callback;
1192	    lower_args.update_barrier_arrive = barrier_arrive_callback;
1193	    lower_args.require_smem_alignment = require_smem_alignment_callback;
1194	
1195	    auto lowered = tile_op->Lower(lower_args, analyzer_);
1196	
1197	    return IRMutatorWithAnalyzer::VisitStmt(lowered);
1198	  }
