1213	  /**
1214	   * @brief Handle a Parallel For node, lowering it based on the layout
1215	   * annotation.
1216	   *
1217	   * This method checks if the For node has a parallel_loop_layout annotation.
1218	   * If the For node is a parallel loop (ForKind::kParallel):
1219	   * - It must have the parallel_loop_layout annotation, otherwise an error is
1220	   *   raised.
1221	   * - The loop is partitioned and vectorized based on the annotated layout.
1222	   * - If a predicate annotation exists, the loop is wrapped with an IfThenElse.
1223	   *
1224	   * Special handling for reducers and local buffers:
1225	   * - If the loop stores into local buffers, thread partitioning is skipped.
1226	   * - If the loop only manipulates local buffers, thread partitioning is
1227	   * skipped.
1228	   * - If reducers are present, vectorization is skipped.
1229	   * - Vectorization is only applied if non-local buffers or vectorizable casts
1230	   *   are present.
1231	   *
1232	   * @return Stmt The lowered statement.
1233	   */
1234	  Stmt VisitStmt_(const ForNode *op) final {
1235	    bool pushed_loop_mbar_phase = false;
1236	    if (op->kind == ForKind::kSerial) {
1237	      int num_stages = 1;
1238	      if (auto ns_anno = op->annotations.Get("num_stages")) {
1239	        if (const auto *ns_int = ns_anno.value().as<IntImmNode>()) {
1240	          if (ns_int->value > 1) {
1241	            num_stages = static_cast<int>(ns_int->value);
1242	          }
1243	        }
1244	      }
1245	      PrimExpr phase_expr;
1246	      DataType loop_dtype = op->loop_var.dtype();
1247	      PrimExpr two = make_const(loop_dtype, 2);
1248	      if (num_stages > 1) {
1249	        PrimExpr num_stages_expr = make_const(loop_dtype, num_stages);
1250	        phase_expr = FloorMod(FloorDiv(op->loop_var, num_stages_expr), two);
1251	      } else {
1252	        phase_expr = FloorMod(op->loop_var, two);
1253	      }
1254	      loop_mbar_phase_stack_.push_back(analyzer_->Simplify(phase_expr));
1255	      pushed_loop_mbar_phase = true;
1256	    }
1257	
1258	    // Extract reducer info from annotations
1259	    Map<Var, ReducerInfo> reducer_info;
1260	    if (op->annotations.count(attr::kReducerInfo)) {
1261	      reducer_info = op->annotations.Get(attr::kReducerInfo)
1262	                         ->as<Map<Var, ReducerInfo>>()
1263	                         .value();
1264	    }
1265	
1266	    // First visit the body.
1267	    For for_node = Downcast<For>(arith::IRMutatorWithAnalyzer::VisitStmt_(op));
1268	    if (pushed_loop_mbar_phase) {
1269	      loop_mbar_phase_stack_.pop_back();
1270	    }
1271	
1272	    // Only process parallel loops
1273	    if (op->kind != ForKind::kParallel) {
1274	      return for_node;
1275	    }
1276	
1277	    // For nested parallel loops, the annotation is placed on the outermost
1278	    // loop. Inner parallel loops without annotation should be skipped here –
1279	    // they will be processed as part of the outer loop's partitioning.
1280	    // Rationale: inner loops cannot govern their outer loops; the outermost
1281	    // loop is the correct place to carry layout so we can rewrite the whole
1282	    // nested region in one place.
1283	    if (!op->annotations.count(attr::kParallelLoopLayout)) {
1284	      return for_node;
1285	    }
1286	
1287	    auto loop_layout = Downcast<Fragment>(
1288	        op->annotations.Get(attr::kParallelLoopLayout).value());
1289	    // Get predicate if it exists
1290	    Optional<PrimExpr> predicate;
1291	    if (op->annotations.count(attr::kParallelLoopPredicate)) {
1292	      predicate = Downcast<PrimExpr>(
1293	          op->annotations.Get(attr::kParallelLoopPredicate).value());
1294	    }
1295	    bool require_padding_guard = false;
1296	    if (auto padding_guard_anno =
1297	            op->annotations.Get(attr::kParallelLoopRequiresPaddingGuard)) {
1298	      if (auto padding_guard_bool =
1299	              padding_guard_anno.value().try_cast<Bool>()) {
1300	        require_padding_guard = padding_guard_bool.value()->value;
1301	      } else if (auto padding_guard_int =
1302	                     padding_guard_anno.value().as<IntImmNode>()) {
1303	        require_padding_guard = padding_guard_int->value != 0;
1304	      } else {
1305	        LOG(WARNING) << "Loop annotation `"
1306	                     << attr::kParallelLoopRequiresPaddingGuard
1307	                     << "` expects Bool value (True/False), but got "
1308	                     << padding_guard_anno.value().GetTypeKey()
1309	                     << ". Ignore override.";
1310	      }
1311	    }
1312	    bool parallel_prefer_async = false;
1313	    if (auto prefer_async_anno = op->annotations.Get(attr::kLoopPreferAsync)) {
1314	      if (auto prefer_async_bool = prefer_async_anno.value().try_cast<Bool>()) {
1315	        parallel_prefer_async = prefer_async_bool.value()->value;
1316	      } else {
1317	        LOG(WARNING) << "Loop annotation `" << attr::kLoopPreferAsync
1318	                     << "` expects Bool value (True/False), but got "
1319	                     << prefer_async_anno.value().GetTypeKey()
1320	                     << ". Ignore override.";
1321	      }
1322	    }
1323	    bool parallel_async_without_async_commit_wait = false;
1324	    if (auto no_commit_wait_anno =
1325	            op->annotations.Get(attr::kParallelAsyncWithoutAsyncCommitWait)) {
1326	      if (auto no_commit_wait_bool =
1327	              no_commit_wait_anno.value().try_cast<Bool>()) {
1328	        parallel_async_without_async_commit_wait =
1329	            no_commit_wait_bool.value()->value;
1330	      } else {
1331	        LOG(WARNING) << "Loop annotation `"
1332	                     << attr::kParallelAsyncWithoutAsyncCommitWait
1333	                     << "` expects Bool value (True/False), but got "
1334	                     << no_commit_wait_anno.value().GetTypeKey()
1335	                     << ". Ignore override.";
1336	      }
1337	    }
1338	
1339	    auto root = GetRef<For>(op);
1340	
1341	    // Check if the loop writes to any non-local buffer or touches a fragment.
1342	    // Thread partitioning is unnecessary when all stores target local buffers
1343	    // and there are no fragment accesses.
1344	    // For example:
1345	    //   for i in T.Parallel(1024):
1346	    //     A_local[i] = A_global[i]
1347	    // Here, A_local is a register-local buffer held independently by each
1348	    // thread, so explicit thread binding is not required.
1349	
1350	    // NOTE: For cases when stores to both local and non-local buffers exist
1351	    // (mixed case), we still conservatively assume that thread partitioning is
1352	    // needed. In such case, the programmer should carefully consider the
1353	    // access patterns of the mixed accesses to ensure correctness.
1354	
1355	    // Element-level intrinsics (e.g. atomic_add) pass non-local buffer
1356	    // pointers via tvm_access_ptr / tl::access_ptr inside CallNodes.
1357	    bool has_non_local_store = false;
1358	    bool has_fragment_access = false;
1359	    PostOrderVisit(root, [&](const ObjectRef &obj) {
1360	      if (const auto *load = obj.as<BufferLoadNode>()) {
1361	        if (IsFragmentBuffer(load->buffer)) {
1362	          has_fragment_access = true;
1363	        }
1364	      } else if (const auto *store = obj.as<BufferStoreNode>()) {
1365	        if (IsFragmentBuffer(store->buffer)) {
1366	          has_fragment_access = true;
1367	        }
1368	        if (!IsLocalBuffer(store->buffer)) {
1369	          has_non_local_store = true;
1370	        }
1371	      } else if (const auto *call = obj.as<CallNode>()) {
1372	        if (call->op.same_as(builtin::tvm_access_ptr())) {
1373	          // tvm_access_ptr format: (dtype, data, offset, extent, rw_mask)
1374	          auto buffer_var = call->args[1].as<VarNode>();
1375	          if (buffer_var) {
1376	            Var var = GetRef<Var>(buffer_var);
1377	            auto it = buffer_map_.find(var);
1378	            if (it != buffer_map_.end()) {
1379	              if (IsFragmentBuffer(it->second)) {
1380	                has_fragment_access = true;
1381	              }
1382	              if (!IsLocalBuffer(it->second)) {
1383	                has_non_local_store = true;
1384	              }
1385	            }
1386	          }
1387	        } else if (call->op.same_as(tl::access_ptr())) {
1388	          // tl::access_ptr format: (BufferLoad, extent, rw_mask)
1389	          if (const auto *load = call->args[0].as<BufferLoadNode>()) {
1390	            if (IsFragmentBuffer(load->buffer)) {
1391	              has_fragment_access = true;
1392	            }
1393	            if (!IsLocalBuffer(load->buffer)) {
1394	              has_non_local_store = true;
1395	            }
1396	          }
1397	        } else if (call->op.same_as(builtin::address_of())) {
1398	          // call_extern may pass address_of(non-local-buffer) pointers, and
1399	          // PostOrderVisit reaches the address_of call directly.
1400	          if (const auto *load = call->args[0].as<BufferLoadNode>()) {
1401	            if (IsFragmentBuffer(load->buffer)) {
1402	              has_fragment_access = true;
1403	            }
1404	            if (!IsLocalBuffer(load->buffer)) {
1405	              has_non_local_store = true;
1406	            }
1407	          }
1408	        }
1409	      }
1410	    });
1411	
1412	    // Determine if this loop requires thread partitioning. Fragment accesses
1413	    // must be partitioned together with their layout rewrite: once a logical
1414	    // fragment index is lowered to a physical per-thread slot, the logical loop
1415	    // iteration has to be owned by the corresponding thread.
1416	    bool parallel_loop = has_non_local_store || has_fragment_access;
1417	
1418	    // Check if there are non-local buffer accesses (for vectorization decision)
1419	    bool has_non_local = false;
1420	    PostOrderVisit(for_node->body, [&](const ObjectRef &obj) {
1421	      if (const auto *load = obj.as<BufferLoadNode>()) {
1422	        if (!IsLocalBuffer(load->buffer, /*allow_var*/ true) &&
1423	            !IsFragmentBuffer(load->buffer)) {
1424	          has_non_local = true;
1425	        }
1426	      } else if (const auto *store = obj.as<BufferStoreNode>()) {
1427	        if (!IsLocalBuffer(store->buffer, /*allow_var*/ true) &&
1428	            !IsFragmentBuffer(store->buffer)) {
1429	          has_non_local = true;
1430	        }
1431	      }
1432	    });
1433	
1434	    // Check if reducers are present in the loop body
1435	    // Workaround: if reducer is presented, don't vectorize loop
1436	    // Best solution should be isolate reduction axis out of vectorization
1437	    //
1438	    // Note: reducer_info stores original buffer data vars, but after visiting
1439	    // the body, buffers may have been remapped via var_remap_. We need to find
1440	    // the original var to check against reducer_info.
1441	    bool has_reducer = false;
1442	    PostOrderVisit(for_node->body, [&](const ObjectRef &obj) {
1443	      if (!has_reducer) {
1444	        if (const auto *store = obj.as<BufferStoreNode>()) {
1445	          Var data_var = store->buffer->data;
1446	          // Find the original var if it was remapped
1447	          // var_remap_ maps old_var -> new_var, so we need reverse lookup
1448	          Var original_var = data_var;
1449	          for (const auto &[old_var, new_var] : var_remap_) {
1450	            if (new_var.same_as(data_var)) {
1451	              original_var = old_var;
1452	              break;
1453	            }
1454	          }
1455	          has_reducer = reducer_info.count(original_var) != 0;
1456	        }
1457	      }
1458	    });
1459	
1460	    // Check if vectorizable cast operations exist
1461	    bool has_cast_operations = false;
1462	    PostOrderVisit(for_node->body, [&](const ObjectRef &obj) {
1463	      if (const auto *cast = obj.as<CastNode>()) {
1464	        DataType from_ty = cast->value.dtype();
1465	        DataType target_ty = cast->dtype;
1466	        if (IsCudaVectorizableCast(from_ty, target_ty) &&
1467	            TargetIsCuda(Target::Current())) {
1468	          has_cast_operations = true;
1469	        }
1470	      }
1471	    });
1472	
1473	    // Decide whether to vectorize:
1474	    // - Only if there are non-local buffers or vectorizable casts
1475	    // - AND no reducers are present
1476	    bool should_vectorize =
1477	        (has_non_local || has_cast_operations) && !has_reducer;
1478	    // Lower the parallel loop using the common function
1479	    Stmt lowered = LowerParallelLoop(
1480	        for_node, loop_layout, CurrentThreadIndex(), analyzer_, layout_map_,
1481	        predicate, parallel_loop, should_vectorize, require_padding_guard);
1482	
1483	    // Only parallel-loop lowering needs PTX cp.async injection. Thread-level
1484	    // lowering does not require converting eligible global->shared copies to
1485	    // `tir.ptx_cp_async`.
1486	    if (TargetCudaHasAsyncCopy(target_)) {
1487	      tvm::transform::PassContext ctx = tvm::transform::PassContext::Current();
1488	      bool auto_async_copy_enabled =
1489	          ctx->GetConfig<Bool>(kEnableAsyncCopy, Bool(true)).value();
1490	      bool should_inject_async_copy =
1491	          parallel_prefer_async ||
1492	          (auto_async_copy_enabled && parallel_async_without_async_commit_wait);
1493	      if (should_inject_async_copy) {
1494	        auto inject_result = InjectPTXAsyncCopy(
1495	            lowered, parallel_async_without_async_commit_wait);
1496	        lowered = inject_result.stmt;
1497	      }
1498	    }
1499	    return lowered;
1500	  }
1501	
1502	  Range CurrentThreadBounds() const {
1503	    return ComputeThreadBounds(thread_binding_, *analyzer_);
1504	  }
1505	
1506	  // Logical thread index handed to lowering helpers: the real threadIdx.x
1507	  // Var when a thread_extent binding exists, otherwise constant 0 (e.g. CPU
1508	  // serial launch). Never an unbound synthetic Var.
1509	  PrimExpr CurrentThreadIndex() const {
1510	    if (thread_binding_.defined()) {
1511	      return thread_binding_->var;
1512	    }
1513	    return IntImm(DataType::Int(32), 0);
1514	  }
1515	
1516	  void RecordSafeValueAnnotations(const SBlockNode *op) {
1517	    if (!op->annotations.count(attr::kSafeValueMap)) {
1518	      return;
1519	    }
1520	    auto map = Downcast<Map<Var, PrimExpr>>(
1521	        op->annotations.Get(attr::kSafeValueMap).value());
1522	    for (const auto &[var, safe_value] : map) {
1523	      safe_value_map_.Set(var, safe_value);
1524	    }
1525	  }
1526	
1527	  Target target_;
1528	  Map<String, Any> block_annotations_;
1529	  Map<Var, Buffer> buffer_data_to_buffer_;
1530	  Map<Var, PrimExpr> safe_value_map_;
1531	  Map<Buffer, Layout> layout_map_;
1532	  Map<Buffer, Layout> layout_remap_;
1533	  Map<Buffer, Buffer> buffer_remap_;
1534	  // Real threadIdx.x binding of the enclosing thread_extent scope, when one
1535	  // exists. Stays undefined for targets without thread bindings (e.g. CPU).
1536	  IterVar thread_binding_;
1537	  size_t thread_block_size_ = 0;
1538	  // Product of cluster_dims from block annotation (default 1).
1539	  int cluster_size_ = 1;
1540	  // Stack of per-Block workspace buffers gathered while visiting children
1541	  std::vector<Array<Buffer>> workspace_stack_;
1542	  // Counter and arrive-counts for mbarrier allocation via
1543	  // alloc_mbarrier callback. Used to inject a barrier buffer with
1544	  // barrier_init annotation into the root block after all tile ops are lowered.
1545	  int mbarrier_count_{0};
1546	  std::vector<int> mbarrier_arrive_counts_;
1547	  // The shared.barrier scope buffer created lazily by alloc_mbarrier callback.
1548	  Optional<Buffer> mbarrier_buffer_;
1549	  // Fallback mbarrier parity derived from the nearest enclosing serial loop.
1550	  std::vector<PrimExpr> loop_mbar_phase_stack_;
1551	  // For ptx Node, we need to remap the buffer and indices
1552	  // By access CallNode instead of BufferLoad Node.
1553	  bool is_ptx_{false};
1554	  std::unordered_map<Var, PrimExpr, ObjectPtrHash, ObjectPtrEqual>
1555	      bind_var_to_expr_;
1556	  // Mapping from data Var of a Buffer to Buffer, for lookup
1557	  std::unordered_map<Var, Buffer, ObjectPtrHash, ObjectPtrEqual> buffer_map_;
1558	  Map<Var, Var> var_remap_;
1559	  bool has_tma_{false};
1560	  // Flag to indicate we are inside a TMA context (tma_load, tma_load_im2col,
1561	  // tma_store). When true, HandleAccessPtrAndOffset only updates buffer data
1562	  // without recomputing indices, since swizzle is encoded in TMA descriptor
1563	  // parameters rather than in memory indices.
1564	  bool in_tma_context_{false};
1565	  // Pending barrier arrive-count overrides from multi-TMA cluster copies.
1566	  std::unordered_map<Var, PrimExpr, ObjectPtrHash, ObjectPtrEqual>
1567	      barrier_arrive_updates_;
1568	  // Per-buffer shared-memory alignment requirements (bytes) reported by op
1569	  // lowerings via the require_smem_alignment callback, keyed by the data Var's
1570	  // name hint. Written back as the kSmemAlignmentMap PrimFunc attribute.
1571	  Map<String, IntImm> smem_alignment_map_;
1572	};
1573	
1574	namespace transform {
1575	
1576	using namespace tirx::transform;
1577	
1578	tvm::transform::Pass LowerTileOp() {
1579	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
1580	    return LowerTileOpPass::Substitute(std::move(f));
1581	  };
1582	  return CreatePrimFuncPass(pass_func, 0, "tl.LowerTileOp", {});
1583	}
1584	
1585	TVM_FFI_STATIC_INIT_BLOCK() {
1586	  namespace refl = reflection;
1587	  refl::GlobalDef().def("tl.transform.LowerTileOp", LowerTileOp);
1588	}
1589	} // namespace transform
1590	
1591	} // namespace tl
1592	} // namespace tvm
