49	  // IR elements are 8-bit unpacked SMEM slots, but TMA/mbarrier transactions
50	  // count the packed FP4 payload loaded from global memory.
51	  if (dtype.is_float4_e2m1_unpacked()) {
52	    return 4;
53	  }
54	  return dtype.bits();
